from common import Q, V
Q("hadith",1,"Who narrated the hadith 'Actions are only by intentions'?","Umar ibn al-Khattab",["Abu Hurayrah","Aishah","Anas ibn Malik"],"It opens Sahih al-Bukhari and is narrated by Umar from the Prophet ﷺ.","Sahih al-Bukhari 1; Sahih Muslim 1907")
Q("hadith",1,"Which book is considered the most authentic after the Quran?","Sahih al-Bukhari",["Sunan Ibn Majah","Musnad Ahmad","Al-Muwatta"],"The scholars of hadith hold Sahih al-Bukhari, then Sahih Muslim, as the most authentic books after the Quran.","Ibn as-Salah, Muqaddimah")
Q("hadith",1,"Who compiled Sahih Muslim?","Imam Muslim ibn al-Hajjaj",["Imam al-Bukhari","Imam at-Tirmidhi","Imam Malik"],"Imam Muslim ibn al-Hajjaj of Nishapur (d. 261 AH) compiled it.","Siyar A'lam an-Nubala")
Q("hadith",2,"What are the six major hadith collections called?","Al-Kutub as-Sittah",["Al-Arba'in","As-Sihah al-Khamsah","Al-Masanid"],"Bukhari, Muslim, Abu Dawud, Tirmidhi, an-Nasa'i and Ibn Majah are known as the Six Books.","Standard classification")
Q("hadith",1,"Which Companion narrated the most hadith?","Abu Hurayrah",["Abu Bakr","Umar","Ibn Mas'ud"],"Abu Hurayrah narrated over 5,000 hadith; he stayed close to the Prophet ﷺ to learn.","Sahih al-Bukhari 118")
Q("hadith",2,"The famous 'Hadith of Jibril' explains which three levels of the religion?","Islam, Iman and Ihsan",["Salah, Zakat and Sawm","Quran, Sunnah and Ijma","Tawbah, Sabr and Shukr"],"Jibril came as a man and asked about Islam, Iman, Ihsan and the Hour.","Sahih Muslim 8")
Q("hadith",2,"How did the Prophet ﷺ define Ihsan?","To worship Allah as though you see Him",["To give charity secretly","To pray at night","To be kind to parents"],"'…and if you do not see Him, He surely sees you.'","Sahih Muslim 8")
Q("hadith",1,"Islam is built upon how many pillars?","5",["3","6","7"],"Shahadah, salah, zakat, Hajj and fasting Ramadan.","Sahih al-Bukhari 8")
Q("hadith",1,"Complete: 'None of you truly believes until he loves for his brother…'","what he loves for himself",["more than his family","as he loves his parents","for the sake of reward"],"Wanting good for others is part of complete faith.","Sahih al-Bukhari 13")
Q("hadith",1,"According to the hadith, who is truly strong?","One who controls himself when angry",["One who wins every wrestle","One who never cries","One with many friends"],"'The strong man is not the good wrestler; the strong man is the one who controls himself when angry.'","Sahih al-Bukhari 6114")
Q("hadith",1,"What did the Prophet ﷺ say about smiling at your brother?","It is charity (sadaqah)",["It is disliked","It breaks wudu","It is only for Eid"],"'Your smiling in the face of your brother is charity.'","Sunan at-Tirmidhi 1956")
Q("hadith",2,"Which deed did the Prophet ﷺ call 'half of faith'?","Purity (tahur)",["Fasting","Charity","Patience"],"'Purity is half of faith.'","Sahih Muslim 223")
Q("hadith",1,"Who are 'the best of you' according to the hadith?","Those who learn the Quran and teach it",["Those who are richest","Those who travel most","Those who speak most"],"'The best of you are those who learn the Quran and teach it.'","Sahih al-Bukhari 5027")
Q("hadith",1,"Whoever believes in Allah and the Last Day should…","speak good or remain silent",["speak loudly","never laugh","only speak Arabic"],"Guarding the tongue is a sign of faith.","Sahih al-Bukhari 6018")
Q("hadith",2,"What is a Hadith Qudsi?","Words from Allah conveyed by the Prophet ﷺ in his own wording",["A hadith narrated in Jerusalem","A verse of the Quran","A weak narration"],"Its meaning is from Allah, its wording from the Prophet ﷺ, and it is not recited as Quran.","Al-Jurjani, at-Ta'rifat")
Q("hadith",3,"What does 'mutawatir' mean in hadith science?","Narrated by so many that agreeing on a lie is impossible",["Narrated by a single Companion","Having a broken chain","Narrated only in Madinah"],"Mutawatir reports give certain knowledge.","Ibn Hajar, Nukhbat al-Fikar")
Q("hadith",2,"What is the chain of narrators of a hadith called?","Isnad",["Matn","Sharh","Takhrij"],"The isnad is the chain; Abdullah ibn al-Mubarak said it is part of the religion.","Sahih Muslim, Muqaddimah")
Q("hadith",2,"What is the text of a hadith called?","Matn",["Isnad","Rawi","Hukm"],"The matn is the actual wording after the chain.","Ibn Hajar, Nukhbat al-Fikar")
Q("hadith",1,"Who compiled the famous 'Forty Hadith' (al-Arba'in)?","Imam an-Nawawi",["Imam al-Ghazali","Imam Ahmad","Imam Abu Hanifa"],"Imam Yahya ibn Sharaf an-Nawawi (d. 676 AH) gathered 42 foundational hadith.","Al-Arba'in an-Nawawiyyah")
Q("hadith",2,"Who compiled al-Muwatta?","Imam Malik",["Imam ash-Shafi'i","Imam Abu Dawud","Imam ad-Darimi"],"Imam Malik ibn Anas of Madinah compiled it, one of the earliest hadith books.","Al-Muwatta")
Q("hadith",2,"Who compiled the Musnad, a huge collection arranged by Companion?","Imam Ahmad ibn Hanbal",["Imam Muslim","Imam an-Nasa'i","Imam Ibn Majah"],"The Musnad of Imam Ahmad contains around 27,000 narrations.","Musnad Ahmad")
Q("hadith",2,"Complete: 'The religion is…'","sincerity (an-nasihah)",["difficult","only prayer","for scholars"],"'The religion is sincerity: to Allah, His Book, His Messenger, the leaders of the Muslims and their common folk.'","Sahih Muslim 55")
Q("hadith",2,"What should you do with something you are in doubt about?","Leave it for what you are not in doubt about",["Do it quickly","Ask only friends","Do it in secret"],"'Leave what makes you doubt for what does not make you doubt.'","Sunan at-Tirmidhi 2518; an-Nasa'i 5711")
Q("hadith",1,"What did the Prophet ﷺ say about making things easy?","Make things easy and do not make them difficult",["Always choose the hardest way","Ease is only for travellers","Difficulty is better"],"'Make things easy and do not make them difficult; give glad tidings and do not drive people away.'","Sahih al-Bukhari 69")
Q("hadith",1,"Which deeds are most beloved to Allah?","The most consistent, even if small",["The biggest, even if rare","Only those done in Ramadan","Only those seen by others"],"Consistency is beloved to Allah.","Sahih al-Bukhari 6464")
Q("hadith",1,"Modesty (haya) is described in the hadith as…","a branch of faith",["a weakness","only for women","a cultural habit"],"'Haya is a branch of iman.'","Sahih al-Bukhari 9")
Q("hadith",1,"Who is a true Muslim according to the hadith?","One from whose tongue and hand people are safe",["One who prays fastest","One who wears special clothes","One who speaks Arabic"],"'The Muslim is the one from whose tongue and hand the Muslims are safe.'","Sahih al-Bukhari 10")
Q("hadith",2,"Which two phrases are 'light on the tongue, heavy on the scale'?","Subhan Allahi wa bihamdihi, Subhan Allahil-Azim",["Allahu Akbar, La ilaha illallah","Astaghfirullah, Alhamdulillah","Bismillah, Ma sha Allah"],"These two phrases are beloved to the Most Merciful.","Sahih al-Bukhari 6406")
Q("hadith",1,"Who did the Prophet ﷺ say most deserves your good companionship?","Your mother (said three times), then your father",["Your friend","Your teacher","Your neighbour"],"He ﷺ said 'your mother' three times, then 'your father'.","Sahih al-Bukhari 5971")
Q("hadith",3,"Imam al-Bukhari was from which city?","Bukhara",["Baghdad","Nishapur","Cairo"],"Muhammad ibn Isma'il al-Bukhari was born in Bukhara (in today's Uzbekistan) in 194 AH.","Siyar A'lam an-Nubala")
Q("hadith",2,"Whoever relieves a believer of a hardship in this world…","Allah will relieve him of a hardship on the Day of Judgement",["will become rich","need not pray","will be famous"],"Helping others brings Allah's help.","Sahih Muslim 2699")
Q("hadith",2,"According to the hadith, what does Allah look at?","Your hearts and your deeds",["Your bodies and faces","Your wealth","Your family name"],"'Allah does not look at your forms or your wealth, but at your hearts and deeds.'","Sahih Muslim 2564")
Q("hadith",2,"What did the Prophet ﷺ say about whoever treads a path seeking knowledge?","Allah makes easy for him a path to Paradise",["He must travel far","He must be rich","He becomes a ruler"],"Seeking knowledge is a road to Paradise.","Sahih Muslim 2699")

# --- Fiqh: consensus questions
Q("fiqh",1,"How many obligatory (fard) daily prayers are there?","5",["3","4","6"],"Five daily prayers were made obligatory on the night of the Mi'raj.","Sahih al-Bukhari 349")
Q("fiqh",1,"How many fard rak'ahs are in Fajr?","2",["3","4","1"],"Fajr has two fard rak'ahs.","Sahih al-Bukhari 350")
Q("fiqh",1,"How many fard rak'ahs are in Maghrib?","3",["2","4","5"],"Maghrib is three rak'ahs for both resident and traveller.","Sahih al-Bukhari 1091")
Q("fiqh",1,"What percentage of zakatable wealth is given as zakat?","2.5%",["5%","10%","20%"],"Zakat on money and trade goods is one fortieth (2.5%).","Sunan Abi Dawud 1572")
Q("fiqh",2,"How long must wealth above the nisab be held before zakat is due?","One lunar year (hawl)",["One month","Six months","One solar decade"],"Zakat is due after a full lunar year passes on the nisab.","Sunan Abi Dawud 1573")
Q("fiqh",2,"When should Zakat al-Fitr be given?","Before the Eid prayer",["After Eid","Any time in the year","Only on the 1st of Ramadan"],"The Prophet ﷺ ordered it to be given before people go out to the Eid prayer.","Sahih al-Bukhari 1509")
Q("fiqh",1,"When may tayammum (dry ablution) be performed?","When water is unavailable or cannot be used",["Whenever one is in a hurry","Only on Fridays","Only while travelling by sea"],"'…and you find no water, then seek clean earth.'","Quran 4:43; 5:6")
Q("fiqh",2,"Which day of Hajj is the Day of Arafah?","9th Dhul Hijjah",["8th Dhul Hijjah","10th Dhul Hijjah","1st Muharram"],"The Prophet ﷺ said: 'Hajj is Arafah.'","Sunan at-Tirmidhi 889")
Q("fiqh",1,"What is the ruling of the Jumu'ah prayer for adult resident men?","Fard (obligatory)",["Optional","Sunnah","Only in Ramadan"],"'O you who believe, when the call is made for prayer on Friday, hasten to the remembrance of Allah.'","Quran 62:9")
Q("fiqh",1,"At which of these times is prayer prohibited?","Exactly at sunrise",["After Dhuhr","Before Isha","After Maghrib"],"Prayer is not offered as the sun rises, at its zenith, and as it sets.","Sahih Muslim 831")
Q("fiqh",2,"How many rak'ahs of Taraweeh do the four madhhabs hold as the established practice?","20",["8","11","4"],"Twenty rak'ahs is the practice from the time of Umar in all four schools (the Malikis also record 36 in old Madinah).","Al-Muwatta 1/115; al-Mughni 2/604")
Q("fiqh",1,"What is the direction faced in salah called?","Qiblah",["Mihrab","Minbar","Qubbah"],"Muslims face the Kaaba in Makkah.","Quran 2:144")
Q("fiqh",1,"What makes ghusl (full bath) obligatory?","Major ritual impurity (janabah)",["Eating meat","Sleeping","Laughing"],"'If you are in a state of janabah, purify yourselves.'","Quran 5:6")
Q("fiqh",1,"What is the call made just before the fard prayer begins in the masjid?","Iqamah",["Adhan","Takbir","Tasbih"],"The adhan calls people; the iqamah announces the prayer is starting.","Sahih al-Bukhari 605")
Q("fiqh",2,"When a traveller shortens Dhuhr, it becomes how many rak'ahs?","2",["3","1","4"],"Four-rak'ah prayers are shortened to two when travelling.","Sahih al-Bukhari 1090")
Q("fiqh",2,"For a traveller, how long may one wipe over leather socks (khuffs)?","Three days and nights",["One day","A week","Forever"],"The Prophet ﷺ set three days and nights for the traveller and one day and night for the resident.","Sahih Muslim 276")
Q("fiqh",1,"Which act ends the salah?","Saying the salam",["Standing up","Raising the hands","Sajdah"],"'Its closing is the taslim.'","Sunan Abi Dawud 61")

